def circular_minimax_partition(values: list, groups: int) -> int:
    """
    Values are non-negative integers arranged in a circle. Cut the circle
    into exactly `groups` nonempty contiguous segments. Segment sums include
    every value exactly once. Return the smallest possible value of the
    largest segment sum.

    A segment may wrap from the end of the list to the beginning. Rotating
    the circle is allowed, and segments are unlabeled, so only the minimum
    possible maximum sum matters. `1 <= groups <= len(values)`.

    >>> circular_minimax_partition([4,1,2,3], 2)
    5
    >>> circular_minimax_partition([8,1,1,8], 2)
    9
    """
    n = len(values)
    if n == 0:
        return 0
    if groups == 1:
        return sum(values)
    if groups >= n:
        return max(values)
    arr2 = values + values
    m = 2 * n

    def can(limit: int) -> bool:
        nxt = [0] * m
        j = 0
        cur_sum = 0
        for i in range(m):
            while j < m and cur_sum + arr2[j] <= limit:
                cur_sum += arr2[j]
                j += 1
            nxt[i] = j
            if j == i:
                j += 1
            else:
                cur_sum -= arr2[i]
        LOG = n.bit_length()
        up = [nxt]
        for k in range(1, LOG):
            prev = up[-1]
            cur = [0] * m
            for i in range(m):
                cur[i] = prev[prev[i]] if prev[i] < m else prev[i]
            up.append(cur)
        for start in range(n):
            pos = start
            target = start + n
            jumps = 0
            for k in range(LOG - 1, -1, -1):
                nxt_pos = up[k][pos]
                if nxt_pos < target:
                    pos = nxt_pos
                    jumps += 1 << k
            jumps += 1
            if jumps <= groups:
                return True
        return False
    low, high = (max(values), sum(values))
    while low < high:
        mid = (low + high) // 2
        if can(mid):
            high = mid
        else:
            low = mid + 1
    return low

